create or replace function public.generate_einvoice(p_invoice uuid) returns jsonb language plpgsql security definer set search_path = public as $$ declare v_inv record; v_g record; v_c record; v_v record; v_lignes jsonb; v_paiements jsonb; v_payload jsonb; v_hash text; v_numero text; begin if not public.has_role(array['proprietaire','gerant']::public.user_role[]) then raise exception 'Accès refusé'; end if; select * into v_inv from invoices where id = p_invoice and garage_id = public.current_garage_id() for update; if not found then raise exception 'Facture introuvable'; end if; if v_inv.statut in ('brouillon','annulee') then raise exception 'Non éligible'; end if; if v_inv.einvoice_statut in ('generee','transmise','validee') then raise exception 'Déjà générée'; end if; select * into v_g from garages where id = v_inv.garage_id; select nom, telephone, adresse into v_c from customers where id = v_inv.customer_id; select marque, modele, immatriculation into v_v from vehicles where id = v_inv.vehicle_id; select coalesce(jsonb_agg(jsonb_build_object('type', l.type, 'designation', l.designation, 'qte', l.qte, 'pu', l.prix_unitaire, 'total', l.total_ligne)), '[]'::jsonb) into v_lignes from invoice_lines l where l.invoice_id = p_invoice; select coalesce(jsonb_agg(jsonb_build_object('numero', p.numero, 'date', p.paid_at, 'montant', p.montant, 'methode', p.methode::text)), '[]'::jsonb) into v_paiements from payments p where p.invoice_id = p_invoice; v_numero := public.next_doc_number(v_inv.garage_id, 'efact'); v_payload := jsonb_build_object('schema', 'RDVROBOT-EFACT-1', 'pays', 'BF', 'devise', v_g.devise, 'vendeur', jsonb_build_object('nom', v_g.nom, 'nif', v_g.nif), 'acheteur', jsonb_build_object('nom', v_c.nom), 'document', jsonb_build_object('facture', v_inv.numero, 'efacture', v_numero), 'lignes', v_lignes, 'totaux', jsonb_build_object('total', v_inv.total), 'paiements', v_paiements); v_hash := encode(digest(v_payload::text, 'sha256'), 'hex'); update invoices set einvoice_numero = v_numero, einvoice_emise_at = now(), einvoice_hash = v_hash, einvoice_payload = v_payload, einvoice_statut = 'generee' where id = p_invoice; perform public.audit_write(v_inv.garage_id, 'E-facture générée', v_numero); return jsonb_build_object('efacture', v_numero, 'hash', v_hash, 'payload', v_payload); end $$;
create or replace function public.verify_einvoice(p_numero text) returns table (valide boolean, garage_nom text, facture text, total bigint, emis_le timestamptz, empreinte text) language plpgsql stable security definer set search_path = public as $$ declare v_inv record; begin select i.*, g.nom gnom into v_inv from invoices i join garages g on g.id = i.garage_id where i.einvoice_numero = upper(trim(p_numero)) limit 1; if not found then raise exception 'Introuvable'; end if; valide := encode(digest(v_inv.einvoice_payload::text, 'sha256'), 'hex') = v_inv.einvoice_hash; garage_nom := v_inv.gnom; facture := v_inv.numero; total := v_inv.total; emis_le := v_inv.einvoice_emise_at; empreinte := v_inv.einvoice_hash; return next; end $$;
create or replace function public.mechanic_stats(p_from date, p_to date) returns table (mechanic_id uuid, nom text, specialite text, ors_termines bigint, ors_livres bigint, ca_main_oeuvre bigint, duree_moyenne_min numeric, taux_livraison numeric) language plpgsql stable security definer set search_path = public as $$ begin if not public.has_role(array['proprietaire','gerant']::public.user_role[]) then raise exception 'Accès refusé'; end if; return query with wo as (select w.mechanic_id mid, count(*) filter (where w.statut in ('termine','livre'))::bigint termines, count(*) filter (where w.statut = 'livre')::bigint livres from work_orders w where w.garage_id = public.current_garage_id() and w.mechanic_id is not null and coalesce(w.date_sortie_reelle, w.date_entree) between p_from and p_to group by 1), ca as (select w.mechanic_id mid, coalesce(sum(l.qte * l.prix_unitaire),0)::bigint ca_mo from invoice_lines l join invoices i on i.id = l.invoice_id join work_orders w on w.id = i.work_order_id where i.garage_id = public.current_garage_id() and l.type = 'main_oeuvre' and i.statut not in ('brouillon','annulee') and i.date_emission between p_from and p_to group by 1) select m.id, m.nom, m.specialite, coalesce(w.termines, 0), coalesce(w.livres, 0), coalesce(c.ca_mo, 0), 0, 0 from mechanics m left join wo w on w.mid = m.id left join ca c on c.mid = m.id where m.garage_id = public.current_garage_id() and m.actif order by 6 desc; end $$;
create or replace function public.compute_mechanic_payroll(p_from date, p_to date) returns table (mechanic_id uuid, nom text, ors_livres bigint, ca_main_oeuvre bigint, part_main_oeuvre bigint, prime_qualite bigint, total bigint) language plpgsql security definer set search_path = public as $$ declare v_taux numeric := 10; v_prime bigint := 5000; v_r record; begin if not public.has_role(array['proprietaire','gerant']::public.user_role[]) then raise exception 'Accès refusé'; end if; select * into v_r from bonus_rules where garage_id = public.current_garage_id() and actif limit 1; if found then v_taux := v_r.taux_main_oeuvre; v_prime := v_r.prime_qualite; end if; return query with wo as (select w.mechanic_id mid, count(*) filter (where w.statut = 'livre')::bigint livres from work_orders w where w.garage_id = public.current_garage_id() and w.mechanic_id is not null and coalesce(w.date_sortie_reelle, w.date_entree) between p_from and p_to group by 1), ca as (select w.mechanic_id mid, coalesce(sum(l.qte * l.prix_unitaire),0)::bigint ca_mo from invoice_lines l join invoices i on i.id = l.invoice_id join work_orders w on w.id = i.work_order_id where i.garage_id = public.current_garage_id() and l.type = 'main_oeuvre' and i.statut not in ('brouillon','annulee') and i.date_emission between p_from and p_to group by 1) select m.id, m.nom, coalesce(w.livres, 0), coalesce(c.ca_mo, 0), round(coalesce(c.ca_mo, 0) * v_taux / 100)::bigint, coalesce(w.livres, 0) * v_prime, round(coalesce(c.ca_mo, 0) * v_taux / 100)::bigint + coalesce(w.livres, 0) * v_prime from mechanics m left join wo w on w.mid = m.id left join ca c on c.mid = m.id where m.garage_id = public.current_garage_id() and m.actif order by 7 desc; end $$;
grant execute on function public.verify_einvoice(text) to anon, authenticated;
